mapper.select:
select
c1.C_Name as qspCname,
c2.C_Name as qspSbCname,
u1.U_Name as qspSbUname,
dp.D_Name as qspSbDname,
mn.*
from  Qs_Plan mn
LEFT JOIN Sys_Company c1 on c1.C_ID=mn.Qsp_Cid
LEFT JOIN Sys_Company c2 on c2.C_ID=mn.Qsp_Sb_Cid
LEFT JOIN Sys_User u1 on u1.U_ID=mn.Qsp_Sb_Uid
LEFT JOIN Sys_Department dp on dp.D_ID=mn.Qsp_Sb_Did

    where 1=1


    ${params.authSql}


    and mn.Te_Id = #{params.teId}


    and mn.Qsp_Project_Type = #{params.qspProjectType}


    and mn.Qsp_Type = #{params.qspType}


    and mn.Qsp_Category = #{params.qspCategory}


    and mn.Qsp_Name like concat('%',#{params.qspName},'%')


    and mn.Qsp_Code like concat('%',#{params.qspCode},'%')


    and mn.Reply_State = #{params.replyState}


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Qsp_Create_Time desc
